static void CGIMP_UnboundSlot(void)
{
    Com_Error( ERR_DROP, "module called an clientGameImport_t import slot that no engine implementation is bound to (see init log for the slot list)" );
}
static void CGIMP_VerifyBound( clientGameImport_t *t )
{
    size_t i;
    for ( i = 0; i < ARRAY_LEN( CGIMP_slots ); i++ ) {
        if ( *( void ** )( ( char * )t + CGIMP_slots[ i ].off ) == NULL ) {
            *( void ** )( ( char * )t + CGIMP_slots[ i ].off ) = ( void * )CGIMP_UnboundSlot;
            Com_DPrintf( "clientGameImport_t slot %s is not backed by this engine yet; calls will error\n", CGIMP_slots[ i ].name );
        }
    }
}
